@startuml

abstract class Contract {
  + getCharges() : double
  + getBalance() : double
  + setBalance(double) : void
}

class BasicContract extends Contract {
  + contractNumber : int
  + balance : double
  + getCharges() : double
  + getBalance() : double
  + setBalance(double) : void
}

abstract class ContractOption extends Contract {}

class DataOption extends ContractOption {}

class SmsOption extends ContractOption {}

class MinutesOption extends ContractOption {}

class TransferRateOption extends ContractOption {}

Contract "1" *-- "0..*" ContractOption

@enduml

